insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source, published_at)
values ('RD-A2-027', 'A2', 'story', 'small_talk', 3, 'Моє дитинство', 'Moje djetinjstvo',
        'Odrastala sam u malom gradu blizu Odese. U djetinjstvu sam ljeta provodila kod bake na selu. Cijele dane smo se igrali vani: skrivača, lovice i školica bile su naše omiljene igre. Bila sam nestašna djevojčica i stalno sam se penjala na drveće. Jednom sam pala i ogrebala koljeno, ali nisam plakala. Navečer nam je baka pričala priče za laku noć. Nismo imali mobitele, ali bili smo bezbrižni i sretni. Danas moja kći Daša odrasta u Zagrebu. Kad joj pričam o svom djetinjstvu, ona ne vjeruje da nismo imali internet.',
        'Я виросла в маленькому місті біля Одеси. У дитинстві я проводила літо в бабусі в селі. Цілими днями ми гралися надворі: хованки, квач і класики були нашими улюбленими іграми. Я була пустотливою дівчинкою і постійно лазила по деревах. Одного разу я впала й подряпала коліно, але не плакала. Увечері бабуся розповідала нам казки на ніч. У нас не було мобільних, але ми були безтурботні й щасливі. Сьогодні моя донька Даша росте в Загребі. Коли я розповідаю їй про своє дитинство, вона не вірить, що в нас не було інтернету.',
        '[{"form": "odrastala", "lemma": "odrastati", "ua": "рости, дорослішати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "минулий час (форма на -l): ж. р., однина"}, {"form": "sam", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: я"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "malom", "lemma": "mali", "ua": "малий", "lesson": true, "pos": "прикметник", "gram": "місцевий відмінок (де? про кого? про що?), однина, ч. р."}, {"form": "gradu", "lemma": "grad", "ua": "місто", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "blizu", "lemma": "blizu", "ua": "поруч / близько", "lesson": true, "pos": "прислівник «близько»; як прийменник — + родовий («blizu tramvaja»)"}, {"form": "odese", "lemma": "Odesa", "ua": "Одеса", "lesson": false, "pos": "назва місця", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "djetinjstvu", "lemma": "djetinjstvo", "ua": "дитинство", "lesson": true, "pos": "іменник, середній рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "ljeta", "lemma": "ljeto", "ua": "літо", "lesson": true, "pos": "іменник, середній рід", "gram": "знахідний відмінок (кого? що?), множина"}, {"form": "provodila", "lemma": "provoditi", "ua": "проводити", "lesson": false, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "минулий час (форма на -l): ж. р., однина"}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false, "pos": "прийменник + родовий відмінок («kod kuće» — вдома, «kod liječnika» — у лікаря)"}, {"form": "bake", "lemma": "baka", "ua": "бабуся", "lesson": true, "pos": "іменник, жіночий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "na", "lemma": "na", "ua":