insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source, published_at)
values ('RD-A2-028', 'A2', 'story', 'small_talk', 3, 'Переїзд, що змінив усе', 'Preseljenje koje je sve promijenilo',
        'Prije tri godine spakirala sam jedan kofer i napustila rodno mjesto. Bilo je teško ostaviti iza sebe kuću, prijatelje i posao. Prvi mjeseci u Hrvatskoj bili su puni neizvjesnosti. Nisam znala jezik i često sam se osjećala izgubljeno. Ponekad mi je bilo teško zbog samoće. Ali susjedi su mi bili velika podrška: susjeda Marija pomogla mi je naći stan, a njezin muž mi je pokazao grad. Polako sam se priviknula na novi život. Kad sam našla posao, osjetila sam veliko olakšanje. Danas mislim da je preseljenje bilo prekretnica u mom životu. Ponosna sam na sebe i na svoju hrabrost.',
        'Три роки тому я спакувала одну валізу й покинула рідне місто. Було важко залишити позаду дім, друзів і роботу. Перші місяці в Хорватії були сповнені невизначеності. Я не знала мови й часто почувалася розгубленою. Іноді мені було важко через самотність. Але сусіди дуже мене підтримали: сусідка Марія допомогла мені знайти квартиру, а її чоловік показав мені місто. Поступово я звикла до нового життя. Коли я знайшла роботу, то відчула велике полегшення. Сьогодні я думаю, що переїзд став поворотним моментом у моєму житті. Я пишаюся собою і своєю сміливістю.',
        '[{"form": "prije", "lemma": "prije", "ua": "до; перед; раніше", "lesson": true, "pos": "прийменник + родовий («prije osam sati»); прислівник «раніше»"}, {"form": "tri", "lemma": "tri", "ua": "три", "lesson": true, "pos": "числівник «три»; після нього іменник у формі як родовий однини"}, {"form": "godine", "lemma": "godina", "ua": "рік", "lesson": true, "pos": "іменник, жіночий рід", "gram": "форма після 2, 3, 4 (як родовий однини)"}, {"form": "spakirala", "lemma": "spakirati", "ua": "спакувати", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "минулий час (форма на -l): ж. р., однина"}, {"form": "sam", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: я"}, {"form": "jedan", "lemma": "jedan", "ua": "один", "lesson": true, "pos": "числівник «один» (відмінюється як прикметник: jedna, jedno)"}, {"form": "kofer", "lemma": "kofer", "ua": "валіза", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "napustila", "lemma": "napustiti", "ua": "покинути, залишити", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "минулий час (форма на -l): ж. р., однина"}, {"form": "rodno", "lemma": "rodno mjesto", "ua": "рідне місце, рідне село", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина, с. р.; частина виразу «rodno mjesto»"}, {"form": "mjesto", "lemma": "rodno mjesto", "ua": "рідне місце, рідне село", "lesson": true, "pos": "сталий вираз", "gram": "частина сталого виразу «rodno mjesto»"}, {"form": "bilo", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "минулий час (форма на -l): с. р., однина"}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); 